from pathlib import Path

pdf_path=Path('/root/employees_backup.pdf')
cols=['ID','First','Last','Dept','Position','Salary','Years','Location','Score']
rows=[]
odd_rows=[]
with pdfplumber.open(pdf_path) as pdf:
    for pno, page in enumerate(pdf.pages):
        tables=page.extract_tables()
        if not tables:
            continue
        for table in tables:
            for row in table:
                if not row or len(row)==0:
                    continue
                if row[0] is None:
                    continue
                if str(row[0]).strip() in ('ID','Id','id'):
                    continue
                if not str(row[0]).strip().startswith('EMP'):
                    # skip row if doesn't look like employee
                    odd_rows.append((pno,row))
                    continue
                if len(row)!=len(cols):
                    odd_rows.append((pno,row))
                rows.append(row)

print('rows', len(rows))
print('odd rows', len(odd_rows))
print('sample odd', odd_rows[:5])
